{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A tired cartographer spreads a hand-drawn map across a broken cobblestone wall, brass compass spinning, ruined spires on the horizon.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp lights up with a warning.",
      "visual_description": "A small oil lamp hovers above the map, its single eye in the flame burning bright, casting jittering shadows across torn royal banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox sniffs the wind at the broken castle gates.",
      "visual_description": "A clockwork fox with blue glass eyes crouches before two enormous shattered gates, its key-wind tail ticking against the silence.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver surfaces from a cracked window.",
      "visual_description": "A figure in a clear diving helmet rises out of a broken stained-glass window as if it were water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers in the ash-strewn plaza.",
      "visual_description": "Four companions meet around a dry fountain, faded royal banners flapping overhead, the lamp's eye flickering nervously.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "They find the Sleeping Tax Collector slumped at a checkpoint.",
      "visual_description": "An official snores on a ledger-book pillow, stamped papers glued to his sleeves, a toppled lantern beside him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns of an armored patrol rounding the corner.",
      "visual_description": "Oracle Lamp's eye narrows to a slit as the shadow of plated boots stretches long across a moonlit alley wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox lures the patrol away with clattering tricks.",
      "visual_description": "The little metal fox dashes across rooftops, sparks flying from its wound tail, drawing torchlight into a side street.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara charts a path through the cursed tower district.",
      "visual_description": "The cartographer points up at three crooked black towers leaning together, ink running on her map from a sudden cold wind.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver slips through a tower mirror.",
      "visual_description": "A tall cracked mirror ripples like a pond as the diver wades inside, his coat trailing reflected fire from a distant blaze.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside, the diver discovers the captive bound in glass.",
      "visual_description": "A dim chamber where a sleeping figure floats inside a column of frosted glass, the diver pressing a gloved hand to its surface.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door refuses to open without a name.",
      "visual_description": "A massive door carved with shifting runes blocks the corridor, the lamp's flame straining toward its keyhole.",
      "characters": ["glass_diver", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox stamps the door with a stolen seal.",
      "visual_description": "The clockwork fox presses a wax-stamped paper, peeled from the sleeping official, against the runes, which flare and split apart.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Rumored wings shadow the rooftops above them.",
      "visual_description": "An enormous winged silhouette passes across the moon, scattering embers; the companions duck under a fallen archway.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver carries the rescued sleeper through a window.",
      "visual_description": "The diver wades through a high arched window as if through water, the freed captive cradled in his reflective coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The Sleeping Tax Collector wakes briefly, then dozes again.",
      "visual_description": "The official blinks at the chaos, stamps a paper labeled APPROVED onto Tin Fox's flank, and slumps back over his ledger.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the long bridge as the city burns behind.",
      "visual_description": "The companions sprint across a narrow stone bridge over a black river, ruined spires glowing orange in the distance.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "On the far shore, Mara folds her map and the lamp dims to a wink.",
      "visual_description": "Dawn breaks over a quiet hillside; the cartographer rolls up her ink-stained map, Tin Fox curled at her boots, Oracle Lamp's eye softening to a sleepy glow beside the rescued sleeper.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

